import data from '../data.json';
import { inCategory, slugs } from './group.js';

export const cats = data.cats;
const ids = slugs(data.items.map(d => d.n));
export const items = data.items.map((d, i) => ({ ...d, i, id: ids[i] }));
export const byId = new Map(items.map(d => [d.id, d])); // for share links: …/#macos-tahoe

const names = Object.fromEntries(cats.map(c => [c.id, c.n]));
export const catName = id => names[id] ?? '';

export const counts = Object.fromEntries(cats.map(c => [c.id, items.filter(d => inCategory(d, c.id)).length]));
